from format_lecon import Lesson,paras,table,steps
l=Lesson('Exotropie intermittente',2)
l.add('L’{exotropie intermittente alterne alignement et déviation vers l’extérieur}. La fusion contrôle la position des yeux pendant une partie du temps. La fréquence de la déviation et son retentissement comptent autant que l’angle.',paras('Les HUG décrivent l’alternance entre position parallèle et position divergente. Le guide RCOphth de 2012 détaille notamment la forme intermittente de loin, dont l’angle est plus important en fixation distante. Toutes les exotropies intermittentes ne doivent pas être assimilées à ce seul sous-type.', 'Une exophorie reste latente tant que la fusion compense. Une exotropie constante ou sensorielle demande une autre caractérisation. Une apparence de contrôle en consultation peut différer du fonctionnement quotidien rapporté par la famille.'),(1,3))
l.add('Le {trouble est souvent remarqué dans l’enfance sans plainte précise}. La fatigue, l’inattention ou une lumière vive peuvent rendre la déviation visible. La trajectoire individuelle justifie une surveillance répétée.',paras('La brochure suisse décrit cette forme comme la plus fréquente des strabismes divergents. Le guide britannique rapporte un début habituel entre 2 et 4 ans pour sa forme intermittente de loin ; ce repère n’exclut pas un diagnostic à un autre âge.', 'Aucune estimation suisse récente et comparable par sous-type n’a été retrouvée. Les pourcentages d’une population sélectionnée ou d’une série chirurgicale ne permettent pas de prédire le devenir d’un enfant précis.', 'La déviation peut rester intermittente ou perdre son contrôle. Les enjeux incluent fonction binoculaire, gêne visuelle, apparence et relations sociales. L’absence de diplopie ne garantit pas l’absence de suppression ou de retentissement sensoriel.'),(1,2,3))
l.add('La {défaillance intermittente de la fusion laisse apparaître la divergence}. Les réserves motrices ne compensent pas toujours la tendance à dévier. Lorsque l’alignement est repris, la vision binoculaire peut redevenir utile.',table(['Mécanisme','Évaluation','Action possible'],[['La fusion contrôle mal la déviation.','Observer la fréquence spontanée et la reprise après dissociation.','Surveiller le contrôle et discuter une intervention s’il se dégrade.'],['Une anomalie réfractive dégrade la qualité de l’image.','Mesurer la réfraction et l’acuité corrigée.','Corriger le défaut optique selon le profil.'],['Une suppression évite parfois la diplopie.','Mesurer stéréoscopie et réponses sensorielles adaptées à l’âge.','Évaluer la fonction binoculaire en plus de l’apparence.'],['Une baisse visuelle rend la fusion impossible.','Comparer les acuités et examiner le fond d’œil.','Rechercher et traiter la cause sensorielle plutôt que supposer une forme intermittente primitive.']])+paras('Le mécanisme précis n’est pas réductible à un unique muscle faible. Une divergence intermittente n’implique pas une paralysie du droit médial. Le guide britannique décrit des réserves fusionnelles variables et distingue convergence, déviation de près et déviation de loin.'),(1,3))
l.add('La {démarche recherche d’abord une baisse visuelle ou une cause acquise}. Une leucocorie ou une déviation soudaine avec signes neurologiques impose un avis urgent. Une motilité anormale ne doit pas être attribuée automatiquement à l’intermittence.',paras('Une exotropie sensorielle accompagne une vision insuffisante d’un œil : l’examen organique est décisif. Une paralysie du III peut associer divergence, ptosis et déficit de plusieurs mouvements ; son apparition acquise exige une évaluation urgente.', 'Une exotropie infantile constante se distingue par son début précoce et son contrôle différent. Une insuffisance de convergence gêne surtout les tâches de près et nécessite une analyse spécifique. Une myasthénie peut imiter une déviation variable, surtout si un ptosis ou une fatigabilité inhabituelle apparaît.', 'La fréquence des épisodes n’est pas un substitut au tri. Une diplopie nouvelle chez un adulte déjà connu pour strabisme peut avoir une autre cause.'),(3,4,5,16))
l.add('L’{anamnèse décrit le contrôle dans la vie quotidienne}. Demander quand l’œil dévie et combien de temps cela semble durer. Rechercher fermeture d’un œil, gêne, diplopie et difficultés scolaires ou sociales.',paras('Les parents peuvent remarquer un œil qui part vers l’extérieur lorsque l’enfant est fatigué, rêve ou regarde au loin. La fermeture d’un œil en lumière vive est un indice décrit par le guide britannique, mais n’est pas un test spécifique.', 'Comparer photographies et observations sans utiliser une image isolée pour mesurer un taux d’aggravation. Demander si l’enfant reprend spontanément l’alignement ou doit cligner des yeux pour retrouver le confort.', 'Préciser les lunettes, les traitements antérieurs et leur tolérance. Interroger directement l’enfant avec des mots simples : une gêne sociale ou une fatigue peuvent ne pas être rapportées spontanément aux parents.'),(1,3))
l.add('L’{examen mesure angle, contrôle et fonction sensorielle}. Observer d’abord l’alignement spontané. Effectuer ensuite les tests de près et de loin, en notant les conditions.',paras('Normalement, la fixation est stable et les mouvements sont complets. Le test à l’écran et le test alterné avec prismes montrent respectivement la déviation manifeste et la déviation totale après dissociation. Noter le temps nécessaire pour reprendre la fixation et l’aide éventuellement requise.', 'Mesurer l’acuité de chaque œil, la réfraction et la stéréoscopie. Une différence de contrôle entre près et loin doit être documentée plutôt qu’effacée dans une seule valeur d’angle.', 'Des mesures répétées sont utiles car la déviation varie. Une limitation motrice, une rétraction du globe, une anomalie pupillaire ou une baisse visuelle inattendue oriente vers un autre mécanisme. Les tests d’occlusion prolongée ou de convergence relèvent du bilan orthoptique indiqué.'),(3,6))
l.add('Les {profils dépendent de la fixation et du contrôle}. Une forme surtout distante diffère d’une gêne prédominante de près. La perte de fonction binoculaire renforce l’indication de réévaluation.',paras('7.1. Une exotropie intermittente de loin se manifeste surtout à distance avec une meilleure coopération de près. Le bilan mesure l’écart entre ces conditions.', '7.2. Une déviation comparable de près et de loin demande une analyse de la fonction globale. Les observations familiales et les tests de stéréoscopie complètent le constat d’angle.', '7.3. Une divergence associée à une faible vision d’un œil est sensorielle jusqu’à clarification. Le signe fonctionnel peut être discret ; l’acuité monoculaire et le fond d’œil identifient le déficit empêchant la fusion.'),(3,))
l.add('Le {diagnostic confirme une exotropie réellement intermittente}. Le contrôle doit être évalué avant et après dissociation. Il n’existe pas de seuil d’angle unique imposant le traitement à tous les patients.',paras('Les critères descriptifs du guide RCOphth de 2012 associent épisodes de divergence, contrôle variable et bilan sensoriel. Pour la forme de loin, la divergence est plus grande en fixation distante. Une convergence normale peut coexister avec cette forme.', 'Documenter fréquence observée et rapportée, récupération de l’alignement, stéréoscopie et gêne. Une seule consultation avec les yeux droits ne suffit pas à invalider une histoire crédible. Inversement, la dissociation alternée peut révéler un angle plus grand que celui visible spontanément.'),(1,3))
l.add('Les {examens reposent principalement sur le bilan orthoptique et réfractif}. Une imagerie n’est pas systématique dans une forme typique stable. Des résultats discordants nécessitent une recherche ciblée.',paras('9.a. L’examen clinique répété caractérise le trouble ; aucun marqueur biologique spécifique n’est disponible.', '9.b. Mesurer acuité, réfraction, angle et fonction binoculaire ; examiner le fond d’œil. Chez l’enfant, la réfraction précise peut demander la cycloplégie selon les conditions suisses détaillées dans le cours général.', '9.c. Si la coopération est insuffisante, adapter les tests et fixer une réévaluation. Les photos renseignent sur l’intermittence mais ne remplacent pas la mesure.', '9.d. Devant une baisse visuelle, une limitation ou un début acquis atypique, demander les examens orientés par la cause suspectée.')+table(['Constat','Interprétation','Conduite'],[['Le contrôle et la stéréoscopie restent stables.','La fonction peut rester satisfaisante malgré l’intermittence.','Poursuivre le suivi individualisé.'],['La déviation devient plus fréquente et se contrôle moins bien.','Une détérioration est possible.','Répéter les mesures et discuter le bénéfice d’une intervention.'],['La vision baisse d’un seul œil.','Une cause sensorielle ou une amblyopie est possible.','Explorer la cause et traiter la vision.'],['Une limitation ou un ptosis apparaît.','Le profil n’est plus celui d’une simple déviation intermittente.','Reprendre le bilan neurologique ou neuromusculaire.']]),(3,6))
l.add('L’{algorithme associe observation et mesures répétées}. Corriger les facteurs visuels puis réévaluer le contrôle. Une aggravation clinique prévaut sur un ancien diagnostic rassurant.',steps('Écarter cause organique, paralysie et signe neurologique urgent.', 'Documenter acuité, réfraction, angles, stéréoscopie et contrôle spontané.', 'Corriger le défaut optique pertinent et traiter une amblyopie si elle existe.', 'Comparer l’évolution dans les mêmes conditions et intégrer la gêne du patient.', 'Si contrôle ou fonction se détériore, discuter traitement spécialisé et chirurgie selon bénéfice, risques et préférences.'),(1,3,6))
l.add('La {prise en charge est adaptée au contrôle et au retentissement}. Une surveillance peut convenir lorsque la fonction reste satisfaisante. Une intervention se discute si la déviation devient gênante ou moins contrôlée.',paras('11.A. Définir les objectifs : maintien de l’acuité, de la stéréoscopie, du confort et d’un alignement utile. Ne pas promettre une guérison définitive à partir d’un taux global de succès chirurgical.', '11.B. Corriger la réfraction selon le bilan. L’occlusion partielle, les verres de surcorrection négative ou des exercices sont des options sélectionnées ; le guide de 2012 indique des incertitudes sur certains bénéfices et sur le moment optimal de chirurgie. Leur choix appartient à l’équipe orthoptique et ophtalmologique, avec contrôle de la vision et de la tolérance.', '11.B. La synthèse Cochrane de 2021 souligne le petit nombre d’essais et les incertitudes sur la meilleure technique ou le moment de la chirurgie. Elle rapporte un bénéfice de l’occlusion dans certaines situations étudiées, sans établir un programme universel. L’observation reste une option lorsque contrôle et fonction le permettent.', '11.B. La chirurgie modifie l’équilibre musculaire lorsque son bénéfice attendu justifie les risques. Les choix techniques et la quantité de chirurgie dépendent des mesures répétées ; aucun nombre universel de millimètres n’est proposé.', '11.C. Une surcorrection postopératoire peut entraîner ésotropie et diplopie, voire menacer le développement visuel de l’enfant. Elle demande un contrôle rapide et un traitement adapté. Une douleur importante ou une baisse de vision postopératoire impose une évaluation urgente.', '11.D. Le suivi recherche récidive, surcorrection, amblyopie et perte de stéréoscopie. Le retour ambulatoire exige des consignes comprises et un contrôle organisé. Chez l’adulte avec diplopie, suspendre les activités dangereuses jusqu’à correction et évaluation. Aucun médicament systémique universel ne traite cette forme de strabisme.'),(1,3,6,17))
l.add('La {prévention vise surtout la détection d’une détérioration}. Informer la famille des signes qui doivent avancer le contrôle. Le suivi persiste après une amélioration apparente.',paras('La prévention primaire d’une exotropie intermittente primitive n’est pas établie dans les sources consultées. La prévention secondaire vérifie réfraction et vision de chaque œil dès la détection.', 'La prévention tertiaire surveille la fonction binoculaire et les récidives après traitement. Une gêne sociale mérite une écoute et des solutions concrètes, même lorsque l’acuité reste bonne. Ne pas imposer des exercices non prescrits comme garantie de guérison.'),(1,2,3))
l.add('Les {points clés portent sur le contrôle et la vision}. L’angle seul ne décide pas de tout. Une baisse d’acuité ou un déficit moteur doit faire rechercher une autre cause.',paras('L’absence de plainte ne prouve pas une bonne vision binoculaire. Mesurer près et loin permet de caractériser la forme. La chirurgie demande des objectifs et un suivi. Une récidive ou une surcorrection peut nécessiter une nouvelle adaptation.'),(1,3,6))
l.quiz([('Une exotropie intermittente est-elle toujours visible ?','Non.'),('L’angle seul décide-t-il de la chirurgie ?','Non ; contrôle, fonction et gêne comptent.'),('La fermeture d’un œil au soleil prouve-t-elle le diagnostic ?','Non ; c’est un indice clinique.'),('Faut-il mesurer la déviation de près et de loin ?','Oui.'),('Une exophorie est-elle identique à une exotropie manifeste ?','Non.'),('Une seule mesure normale annule-t-elle les observations familiales ?','Non ; il faut considérer l’intermittence.'),('Une faible vision d’un œil peut-elle provoquer la divergence ?','Oui ; rechercher une cause sensorielle.'),('Un ptosis nouveau est-il expliqué par défaut par l’exotropie ?','Non.'),('La stéréoscopie doit-elle être suivie ?','Oui lorsqu’elle est mesurable.'),('Les exercices sont-ils une solution universelle ?','Non ; leur indication dépend du profil.'),('Une surveillance sans chirurgie peut-elle être raisonnable ?','Oui si le contrôle, la vision et le retentissement le permettent.'),('La chirurgie exclut-elle toute récidive ?','Non.'),('Une surcorrection peut-elle demander un contrôle rapide ?','Oui, notamment chez l’enfant.'),('Une déviation aiguë avec signes neurologiques attend-elle la consultation programmée ?','Non.')],(1,3,4,5,6))
l.write()
